#include <iostream>

class Wallet {
    int amount{0};
public:
    void deposit(int n) { if (n >= 0) amount += n; }
    bool withdraw(int n) {
        if (n < 0 || n > amount) return false;
        amount -= n;
        return true;
    }
    int balance() const { return amount; }
};

int main() {
    int deposit{}, withdrawal{};
    std::cin >> deposit >> withdrawal;
    Wallet wallet;
    wallet.deposit(deposit);
    const bool ok = wallet.withdraw(withdrawal);
    std::cout << (ok ? "ok" : "rejected") << " " << wallet.balance() << "\n";
}

